import{_ as a,o as i,c as s,a2 as t}from"./chunks/framework.Bum8orMG.js";const k=JSON.parse('{"title":"Upgrade to v2","description":"Migrating KatanaKit from 1.x to 2 — the package became katanakit-js, the code moved to hexagonal architecture, and imports stopped having side effects.","frontmatter":{"title":"Upgrade to v2","description":"Migrating KatanaKit from 1.x to 2 — the package became katanakit-js, the code moved to hexagonal architecture, and imports stopped having side effects."},"headers":[],"relativePath":"guides/upgrade-to/v2.md","filePath":"guides/upgrade-to/v2.md","lastUpdated":1791014171000}'),n={name:"guides/upgrade-to/v2.md"};function o(r,e,d,h,l,p){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="upgrade-to-katanakit-v2" tabindex="-1">Upgrade to KatanaKit v2 <a class="header-anchor" href="#upgrade-to-katanakit-v2" aria-label="Permalink to &quot;Upgrade to KatanaKit v2&quot;">​</a></h1><p>This guide migrates you from <strong>1.x</strong> to <strong>2.x</strong>. Most of v2 was a rework of the codebase rather than of the public API, but two things affect you directly: the package name and the removal of side effects on import.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> katanakit-js@^2</span></span></code></pre></div><h2 id="the-package-was-renamed" tabindex="-1">The package was renamed <a class="header-anchor" href="#the-package-was-renamed" aria-label="Permalink to &quot;The package was renamed&quot;">​</a></h2><p>v2 was developed and published as <strong><code>katanakit-dev</code></strong>. The npm package was renamed to <code>katanakit-js</code> on 2026-09-04 — <code>katanakit-dev</code> is unpublished and can no longer be installed. Every import changes accordingly:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// before (1.x)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { useFetch } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;katanakit-dev&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { useBunCreate } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;katanakit-dev/adapters/bun&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// after (2.x)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { useFetch } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;katanakit-js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { useBunCreate } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;katanakit-js/adapters/bun&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Update <code>package.json</code> and every import in one pass:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;katanakit-dev&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> xargs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;s/katanakit-dev/katanakit-js/g&#39;</span></span></code></pre></div><h2 id="side-effects-on-import-are-gone-2-0-0" tabindex="-1">Side effects on import are gone (2.0.0) <a class="header-anchor" href="#side-effects-on-import-are-gone-2-0-0" aria-label="Permalink to &quot;Side effects on import are gone (2.0.0)&quot;">​</a></h2><p>Importing the library no longer does anything by itself. The top-level <code>fetch</code> to dummyjson.com, the <code>console</code> calls, the storage writes and the timers that 1.x ran at module scope were removed. You opt in by calling a function.</p><p>If you relied on an import &quot;warming up&quot; a service, call its entry point explicitly instead.</p><h2 id="changed-structure-2-0-0" tabindex="-1">Changed structure (2.0.0) <a class="header-anchor" href="#changed-structure-2-0-0" aria-label="Permalink to &quot;Changed structure (2.0.0)&quot;">​</a></h2><p>The project was reorganized into hexagonal architecture: <code>types/</code>, <code>core/services/</code>, <code>infrastructure/</code>, <code>adapters/</code>, <code>config/</code> and <code>prisma/</code>. The public API is exposed through barrel files — <code>src/index.ts</code> and a <code>index.ts</code> per layer — so <strong>your imports keep working</strong>; only deep paths into <code>src/</code> change, and those were never supported.</p><h2 id="fixed-in-v2" tabindex="-1">Fixed in v2 <a class="header-anchor" href="#fixed-in-v2" aria-label="Permalink to &quot;Fixed in v2&quot;">​</a></h2><ul><li>Singleton guards (<code>TimingService</code>, <code>ViewportService</code>) and the <code>FIND_ENTRY</code> scope bug in <code>AstroService</code>.</li><li>Express server: <code>listen</code> honours the configured port/host, the user router is mounted, and handler <code>req</code>/<code>res</code> argument order is correct.</li><li>Logger call sites now pass the level as the <strong>first</strong> argument to <code>useLog</code>.</li><li>TypeScript compile errors in broken imports.</li></ul><h2 id="removed-in-v2" tabindex="-1">Removed in v2 <a class="header-anchor" href="#removed-in-v2" aria-label="Permalink to &quot;Removed in v2&quot;">​</a></h2><p>Duplicate type definitions (unified in <code>src/types/</code>), dead code, empty files and the abandoned signals draft. Demos moved to <code>examples/</code> and the <code>wiki/</code> documentation tree was dropped.</p><h2 id="migration-checklist" tabindex="-1">Migration checklist <a class="header-anchor" href="#migration-checklist" aria-label="Permalink to &quot;Migration checklist&quot;">​</a></h2><ol><li>Rename <code>katanakit-dev</code> to <code>katanakit-js</code> in <code>package.json</code> and all imports.</li><li>Check for anything that depended on import-time side effects and make those calls explicit.</li><li>Run your test suite.</li></ol><p>Full detail per release: <a href="/katanakit-js/changelog">changelog</a>.</p>`,20)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
